F.append(fiche(
    FIL, ["2nde", "1re"], FR,
    "Chapitre F7 · Grammaire et réécriture : propositions et transformations",
    REF_FR + " · programme de français (seconde et première) : « Maîtrise de la langue » ; "
             "notions : subordination, discours indirect, accord du participe passé",
    [
        "Une phrase simple ne contient qu'une proposition indépendante ; une phrase complexe en contient plusieurs, reliées par juxtaposition, coordination ou subordination.",
        "Une proposition subordonnée s'introduit par un mot de liaison : conjonction de subordination (« parce que », « bien que »), pronom relatif (« qui », « que », « dont ») ou mot interrogatif.",
        "La subordonnée relative complète un nom appelé antécédent : dans « le livre que je lis », le pronom « que » reprend « livre » et s'accorde avec lui en genre et en nombre.",
        "La subordonnée complétive complète un verbe de parole ou de pensée et s'introduit généralement par « que » : « Je pense qu'il a raison ».",
        "La subordonnée circonstancielle exprime une circonstance — cause, but, concession, temps ou condition ; les conjonctions « bien que » et « quoique » appellent le subjonctif.",
        "La transformation en voix passive fait passer le complément d'objet direct au rang de sujet : « Le chat mange la souris » devient « La souris est mangée par le chat », avec l'auxiliaire être et le participe passé.",
        "Le passage du discours direct au discours indirect supprime les guillemets, transforme les pronoms et les démonstratifs et décale les temps : « Il a dit : Je viens » devient « Il a dit qu'il venait ».",
        "La nominalisation transforme un verbe ou un adjectif en nom : « Les habitants protestent » devient « la protestation des habitants » ; elle permet de densifier une phrase et d'éviter les répétitions.",
        "Le participe passé employé avec « avoir » s'accorde avec le complément d'objet direct seulement lorsque celui-ci est placé avant le verbe : « les fleurs que j'ai cueillies ».",
        "Avec l'auxiliaire « être » — et avec les verbes pronominaux — le participe passé s'accorde avec le sujet : « Elles sont parties », « Elles se sont lavées ».",
        "L'accord du verbe demande d'identifier le sujet véritable, en particulier après « c'est », « ce sont » ou dans une tournure inversée : « Ce sont mes amis qui arrivent ».",
        "La réécriture du bac porte sur un passage précis : on respecte le sens, le registre et toutes les consignes de forme, sans jamais ajouter d'idée nouvelle ni modifier le contexte.",
    ],
    [
        qcm("Qu'appelle-t-on une proposition indépendante ?", ["Une proposition qui ne dépend d'aucune autre", 'Une proposition introduite par « que »', 'Une proposition sans verbe', 'Une proposition qui suit le verbe'], 0, "Une proposition indépendante peut former une phrase à elle seule ; elle n'est introduite par aucun mot de subordination et ne complète aucune autre proposition."),
        qcm('Quel mot introduit une subordonnée complétive ?', ['Parce que', 'Dont', 'Que', 'Bien que'], 2, "La complétive complète un verbe de parole ou de pensée et s'introduit par « que » : « Je crois qu'il est tard »."),
        qcm('Dans « le film dont je parle », « dont » est :', ['Une conjonction', 'Un pronom relatif', 'Un adverbe', 'Une préposition'], 1, "« Dont » est un pronom relatif employé comme complément d'objet indirect ou complément du nom ; son antécédent est ici « film »."),
        qcm('Quel mode appelle la conjonction « bien que » ?', ["L'indicatif", 'Le subjonctif', "L'impératif", 'Le participe'], 1, "« Bien que » et « quoique » introduisent une concession et exigent le subjonctif : « Bien qu'il pleuve, nous sortons »."),
        qcm('Quelle est la voix passive de « Les élèves écoutent le professeur » ?', ['Le professeur est écouté par les élèves', 'Les élèves sont écoutés par le professeur', 'Le professeur écoute les élèves', 'Les élèves écouteront le professeur'], 0, "Au passif, l'ancien COD devient sujet : « Le professeur est écouté par les élèves ». Le participe passé s'accorde avec le nouveau sujet."),
        qcm('Comment transforme-t-on « Il dit : Je pars » en discours indirect ?', ["Il dit qu'il part", 'Il dit que je pars', "Il a dit : qu'il part", 'Il dit : je partais'], 0, "On supprime les guillemets, on remplace « je » par « il » et on introduit la complétive par « que » : « Il dit qu'il part » (avec un verbe au passé : « Il a dit qu'il partait »)."),
        qcm("Dans « les lettres qu'elle a écrites », pourquoi « écrites » prend-il un « s » ?", ['Parce que le sujet est féminin', 'Parce que le COD « que » est placé avant le verbe et renvoie à « lettres »', "Parce que « avoir » est toujours suivi d'un accord", 'Parce que le verbe est au présent'], 1, "Avec « avoir », le participe passé ne s'accorde que si le COD précède le verbe : ici « que » (= les lettres) est avant « a écrites », donc accord au féminin pluriel."),
        qcm("Qu'est-ce qu'une nominalisation ?", ['Une transformation du nom en verbe', "Une transformation du verbe ou de l'adjectif en nom", 'Une suppression de la ponctuation', 'Un accord du sujet'], 1, 'La nominalisation convertit un verbe ou un adjectif en nom : « ils manifestent » → « leur manifestation ». Elle resserre le style et permet des reprises plus élégantes.'),
        qt("Transformez en voix passive : « Le vent a emporté les feuilles. » puis expliquez l'accord.",
           "« Les feuilles ont été emportées par le vent. » Le complément d'objet direct « les feuilles » devient le sujet du verbe passif ; l'auxiliaire « être » est mis au même temps que « avoir » (passé composé → « ont été »), et le participe passé « emportées » s'accorde en genre et en nombre avec le nouveau sujet féminin pluriel.",
           "On identifie le COD, on l'élève au rang de sujet, on conjugue « être » au temps de l'auxiliaire initial et on accorde le participe passé avec le sujet."),
        qt("Réécrivez au discours indirect : « Marie a dit : Je viendrai demain. »",
           "« Marie a dit qu'elle viendrait le lendemain. » Le verbe introducteur est au passé, donc le futur simple devient conditionnel présent et l'adverbe de temps « demain » devient « le lendemain » ; le pronom « je » est remplacé par « elle », et les guillemets disparaissent.",
           "Il faut vérifier les trois transformations : pronoms, décalage des temps et des adverbes, suppression des marques du discours direct."),
    ],
    [
        bloc("L'idée en une phrase", texte="Maîtriser la phrase, c'est reconnaître les propositions et appliquer les transformations sans changer le sens.", type="intro"),
        bloc("La formule à connaître", eq="Relative → complétive → circonstancielle",
             leg="Qui/que/dont · que · parce que / bien que + subjonctif", type="formule"),
        bloc("Tableau des subordonnées", items=[
            ["Relative", "Qui, que, dont", "Complète un nom"],
            ["Complétive", "Que", "Complète un verbe"],
            ["Circonstancielle", "Parce que, bien que", "Exprime une circonstance"]], type="grille"),
        bloc("À retenir sur les accords", items=[
            "Avec être, le participe s'accorde avec le sujet : « Elles sont parties »",
            "Avec avoir, accord seulement si le COD est avant le verbe",
            "« Les fleurs que j'ai cueillies » : accord avec « que » = fleurs",
            "« Bien que » et « quoique » exigent le subjonctif",
            "Au passif, l'ancien COD devient sujet et le participe s'accorde"], type="liste"),
        bloc("Réécrire, étape par étape", items=[
            "Lire la consigne : temps, personne, voix, ponctuation",
            "Repérer le sujet, le verbe et le complément d'objet direct",
            "Appliquer la transformation demandée",
            "Vérifier tous les accords",
            "Relire la phrase pour vérifier qu'elle garde le même sens"], type="etapes"),
        bloc("Pièges fréquents", items=[
            "Accorder le participe avec « avoir » alors que le COD est après",
            "Oublier le subjonctif après « bien que »",
            "Changer le sens en ajoutant une idée dans la réécriture",
            "Confondre complétive et relative",
            "Mal décaler les temps en discours indirect"], type="attention"),
        bloc("Exemples à maîtriser", items=[
            "<span class=\"cle\">« Les fleurs que j'ai cueillies »</span> → COD antérieur",
            "<span class=\"cle\">« Bien qu'il pleuve »</span> → subjonctif",
            "<span class=\"cle\">« La souris est mangée… »</span> → voix passive",
            "<span class=\"cle\">« Il a dit qu'il venait »</span> → discours indirect",
            "<span class=\"cle\">« Le livre que je lis »</span> → pronom relatif"], type="exemples"),
    ],
    [
        diag("1 · Les types de propositions", svg_grille("Reconnaître une subordonnée",
             ["Type", "Mot introducteur", "Fonction"],
             [["Relative", "Qui, que, dont", "Complète un nom"],
              ["Complétive", "Que", "Complète un verbe"],
              ["Circonstancielle", "Parce que, bien que", "Exprime une circonstance"]])),
        diag("2 · Réécrire une phrase", svg_etapes("Méthode de transformation",
             ["Repérer la consigne (temps, personne, voix)",
              "Identifier le sujet et le complément d'objet direct",
              "Appliquer la transformation sans changer le sens",
              "Vérifier les accords et la ponctuation",
              "Relire la phrase finale à voix haute"])),
        diag("3 · Deux façons de rapporter une parole", svg_compare("Discours direct / indirect",
             ("Discours direct", ["Guillemets et deux-points", "« Je viendrai demain »", "Temps du locuteur", "Présence de l'auditeur"]),
             ("Discours indirect", ["Complétive avec « que »", "« Qu'il viendrait le lendemain »", "Temps décalés", "Pronoms transformés"]))),
    ],
))

